// ─── File: SelfPermitDemo.java ───
// Single runnable file with multiple top-level package-private classes.
package com.bank.selfpermit;

import java.math.BigDecimal;
import java.util.List;
import java.util.logging.*;

public class SelfPermitDemo {
    private static final Logger log = Logger.getLogger(SelfPermitDemo.class.getName());

    static {
        LogManager.getLogManager().reset();
        ConsoleHandler h = new ConsoleHandler();
        h.setFormatter(new BankLogFormatter());
        log.addHandler(h);
        log.setLevel(Level.ALL);
    }

    public static void main(String[] args) {
        // ILLEGAL (does NOT compile):
        //   sealed class Account permits Account {}
        //   → error: cyclic / Account cannot extend itself; a type is not its own subtype.

        // CORRECT 1: a CONCRETE (non-abstract) sealed base is itself usable AND
        // permits real subtypes — this is NOT self-permitting.
        LedgerNode base = new LedgerNode("LED-ROOT", new BigDecimal("0"));
        SummaryNode summary = new SummaryNode("LED-SUM", new BigDecimal("1250000"), 2);
        log.info(() -> "Concrete base usable: " + base.describe());
        log.info(() -> "Permitted subtype:   " + summary.describe());

        // CORRECT 2: RECURSIVE data — a node holds children of the same type.
        // This is composition, NOT a type permitting itself.
        TransactionNode leaf1 = new TransactionNode("TXN-1", new BigDecimal("50000"), List.of());
        TransactionNode leaf2 = new TransactionNode("TXN-2", new BigDecimal("30000"), List.of());
        TransactionNode root  = new TransactionNode("TXN-ROOT", new BigDecimal("0"),
                                                    List.of(leaf1, leaf2));
        log.info(() -> "Recursive total under root = Rs." + root.total());
    }
}

// ─── Would be in model/LedgerNode.java ───
// CONCRETE sealed class: instantiable itself, permits SummaryNode.
// It does NOT permit itself — it permits a DIFFERENT subtype.
sealed class LedgerNode permits SummaryNode {
    private final String id;
    private final BigDecimal amount;
        LedgerNode(String id, BigDecimal amount) { this.id = id;
        this.amount = amount; }
    String id() { return id; }
    BigDecimal amount() { return amount; }
    String describe() { return "LedgerNode " + id + " Rs." + amount; }
}

// ─── Would be in model/SummaryNode.java ───
// FINAL permitted subtype of the concrete sealed base.
final class SummaryNode extends LedgerNode {
    private final int childCount;
        SummaryNode(String id, BigDecimal amount, int childCount) { super(id, amount);
        this.childCount = childCount; }
    @Override String describe() { return "SummaryNode " + id() + " Rs." + amount() + " children=" + childCount; }
}

// ─── Would be in model/TransactionNode.java ───
// RECURSIVE sealed structure: a node holds children of its OWN type.
// A field of the same type is composition — totally different from self-permit.
final class TransactionNode {
    private final String id;
    private final BigDecimal amount;
    private final List<TransactionNode> children;   // same-type field = recursion, legal
    TransactionNode(String id, BigDecimal amount, List<TransactionNode> children) {
            this.id = id;
            this.amount = amount
            this.children = children;
    }
    BigDecimal total() {
        BigDecimal sum = amount;
        for (TransactionNode c : children) sum = sum.add(c.total());  // recurse over data
        return sum;
    }
}

// ─── Would be in util/BankLogFormatter.java ───
class BankLogFormatter extends java.util.logging.Formatter {
    @Override public String format(java.util.logging.LogRecord r) {
        return String.format("%1$tF %1$tT [%2$s] %3$s%n",
            new java.util.Date(r.getMillis()), r.getLevel(), formatMessage(r));
    }
}
